import { extend } from 'flarum/common/extend';
import UserListPage from 'flarum/admin/components/UserListPage';
import Icon from 'flarum/common/components/Icon';
export default function extendUserListPage() {
  extend(UserListPage.prototype, 'columns', function (columns) {
    columns.add('2fa', {
      name: '2FA',
      content: user => {
        return user.twoFactorEnabled() ? m("p", null, m(Icon, {
          name: "fas fa-shield-alt"
        })) : m("p", null);
      }
    }, 82);
  });
}